import{_ as l,o as p,c as t,ai as e}from"./chunks/framework.BxxKhjs3.js";const h="/pub-blog/assets/image-20241024175411585.ByIGqA_U.png",k="/pub-blog/assets/PixPin_2024-10-24_17-54-18.C7-XPgBH.gif",r="/pub-blog/assets/image-20241031111045865.DpO00Vov.png",E="/pub-blog/assets/image-20241031111130741.ByHfofiB.png",d="/pub-blog/assets/image-20241031111326923.DMsr6otr.png",i="/pub-blog/assets/PixPin_2024-10-31_11-27-05.kVEAji8v.gif",g="/pub-blog/assets/image-20241031112238553.2efdGNXG.png",y="/pub-blog/assets/image-20241031111803516.CvWUpMo3.png",a="/pub-blog/assets/PixPin_2024-10-31_13-06-50.BkyHDnjj.gif",c="/pub-blog/assets/image-20241031222230532.DmUOpQNU.png",o="/pub-blog/assets/image-20241031223836426.GZZv7agA.png",n="/pub-blog/assets/PixPin_2024-10-31_20-52-33.B-O8lAzC.gif",F="/pub-blog/assets/image-20241031224019379.CIcrtG03.png",b="/pub-blog/assets/image-20241031224212664.DUmrlMCe.png",m="/pub-blog/assets/PixPin_2024-10-31_22-18-40.C3BYUyCc.gif",v=JSON.parse('{"title":"HarmonyOS Next 实战卡片开发 03","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 实战卡片开发/HarmonyOS Next 实战卡片开发 03/HarmonyOS Next 实战卡片开发 03.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 实战卡片开发/HarmonyOS Next 实战卡片开发 03/HarmonyOS Next 实战卡片开发 03.md","lastUpdated":1730788610000,"__rawMarkdown":"# HarmonyOS Next 实战卡片开发 03\\n\\n在前面两张，我们基本掌握了卡片的使用流程，本章节就通过一个实战来加强对卡片使用的理解。\\n\\n# 要完成的案例\\n\\n![image-20241024175411585](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/image-20241024175411585.png)\\n\\n---\\n\\n![PixPin_2024-10-24_17-54-18](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/PixPin_2024-10-24_17-54-18.gif)\\n\\n\\n\\n# 新建项目和新建服务卡片\\n\\n![image-20241031111045865](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/image-20241031111045865.png)\\n\\n---\\n\\n![image-20241031111130741](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/image-20241031111130741.png)\\n\\n\\n\\n# 设置沉浸式\\n\\n> entry/src/main/ets/entryability/EntryAbility.ets\\n\\n![image-20241031111326923](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/image-20241031111326923.png)\\n\\n# 首页显示轮播图数据\\n\\n![PixPin_2024-10-31_11-27-05](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/PixPin_2024-10-31_11-27-05.gif)\\n\\n## 1. 申请网络权限\\n\\n> entry/src/main/module.json5\\n\\n![image-20241031112238553](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/image-20241031112238553.png)\\n\\n## 2. 新建工具文件 /utils/index.ets \\n\\n> entry/src/main/ets/utils/index.ets\\n\\n```typescript\\nexport const swiperInit = () => {\\n\\n  AppStorage.setOrCreate(\\"swiperList\\", [\\n    \\"https://env-00jxhf99mujs.normal.cloudstatic.cn/card/1.webp?expire_at=1729734506&er_sign=e51cb3b4f4b28cb2da96fd53701eaa69\\",\\n    \\"https://env-00jxhf99mujs.normal.cloudstatic.cn/card/2.webp?expire_at=1729734857&er_sign=b2ffd42585568a094b9ecfb7995a9763\\",\\n    \\"https://env-00jxhf99mujs.normal.cloudstatic.cn/card/3.webp?expire_at=1729734870&er_sign=50d5f210191c113782958dfd6681cd2d\\",\\n  ])\\n  AppStorage.setOrCreate(\\"activeIndex\\", 0)\\n}\\n```\\n\\n\\n\\n## 3. 初始化\\n\\n>  entry/src/main/ets/entryability/EntryAbility.ets\\n\\n![image-20241031111803516](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/image-20241031111803516.png)\\n\\n## 4. 页面中使用\\n\\n> entry/src/main/ets/pages/Index.ets\\n\\n```typescript\\n\\n@Entry\\n@Component\\nstruct Index {\\n  @StorageProp(\\"swiperList\\")\\n  swiperList: string[] = []\\n  @StorageLink(\\"activeIndex\\")\\n  activeIndex: number = 0\\n\\n\\n  build() {\\n    Column() {\\n      Swiper() {\\n        ForEach(this.swiperList, (img: string) => {\\n          Image(img)\\n            .width(\\"80%\\")\\n        })\\n      }\\n      .loop(true)\\n      .autoPlay(true)\\n      .interval(3000)\\n\\n      .onChange(index => this.activeIndex = index)\\n    }\\n    .height(\'100%\')\\n    .width(\'100%\')\\n    .justifyContent(FlexAlign.Center)\\n    .backgroundImage(this.swiperList[this.activeIndex])\\n    .backgroundBlurStyle(BlurStyle.Thin)\\n    .backgroundImageSize(ImageSize.Cover)\\n    .animation({ duration: 500 })\\n  }\\n}\\n```\\n\\n\\n\\n## 5. 效果\\n\\n![PixPin_2024-10-31_11-27-05](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/PixPin_2024-10-31_11-27-05.gif)\\n\\n\\n\\n# 创建卡片时，获取卡片id\\n\\n![PixPin_2024-10-31_13-06-50](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/PixPin_2024-10-31_13-06-50.gif)\\n\\n![image-20241031222230532](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/image-20241031222230532.png)\\n\\n## 1. 获取和返回卡片id\\n\\n这里解析下为什么要返回id给卡片组件，因为后期卡片想要向应用通信时，应用响应数据要根据卡片id来响应。\\n\\n另外 formExtensionAbility进程不能常驻后台，即在卡片生命周期回调函数中无法处理长时间的任务，在生命周期调度完成后会继续存在10秒，如10秒内没有新的\\n\\n生命周期回调触发则进程自动退出。针对可能需要10秒以上才能完成的业务逻辑，建议[拉起主应用](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-ui-widget-event-uiability-V5)进行处理，处理完成后使用[updateForm](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-app-form-formprovider-V5#updateform)通知卡片进行刷新\\n\\n> entry/src/main/ets/entryformability/EntryFormAbility.ets\\n\\n```typescript\\n  onAddForm(want: Want) {\\n    class FormData {\\n      // 获取卡片id\\n      formId: string = want.parameters![\'ohos.extra.param.key.form_identity\'].toString();\\n    }\\n\\n    let formData = new FormData()\\n    return formBindingData.createFormBindingData(formData);\\n  }\\n```\\n\\n\\n\\n## 2. 接受和显示卡片id\\n\\n> entry/src/main/ets/widget/pages/WidgetCard.ets\\n\\n```typescript\\nconst localStorage = new LocalStorage()\\n\\n@Entry(localStorage)\\n@Component\\nstruct WidgetCard {\\n  @LocalStorageProp(\\"formId\\")\\n  formId: string = \\"\\"\\n\\n  build() {\\n    Row() {\\n      Text(this.formId)\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n    .padding(10)\\n\\n  }\\n}\\n```\\n\\n\\n\\n## 3. 效果\\n\\n![PixPin_2024-10-31_13-06-50](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/PixPin_2024-10-31_13-06-50.gif)\\n\\n\\n\\n# 记录卡片id，持久化存储\\n\\n![image-20241031223836426](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/image-20241031223836426.png)\\n\\n主要流程如下：\\n\\n1. 封装持久化存储卡片id的工具类\\n2. 初始化卡片id工具类\\n3. 卡片主动上传卡片id\\n4. 应用Aibility接收卡片id\\n5. 接收卡片id并且持久化\\n6. 移除卡片时，删除卡片id\\n\\n\\n\\n## 1. 封装持久化存储卡片id的工具类\\n\\n此时接收到卡片id后，需要将卡片id持久化存储，避免重新打卡手机时，无法联系到已经创建的卡片\\n\\n> entry/src/main/ets/utils/index.ets\\n\\n```typescript\\nexport class FormIdStore {\\n  static key: string = \\"wsy_collect\\"\\n  static dataPreferences: preferences.Preferences | null = null;\\n  static context: Context | null = null\\n\\n  //  初始化\\n  static init(context?: Context) {\\n    if (!FormIdStore.dataPreferences) {\\n      if (context) {\\n        FormIdStore.context = context\\n      }\\n      FormIdStore.dataPreferences =\\n        preferences.getPreferencesSync(FormIdStore.context || getContext(), { name: FormIdStore.key })\\n    }\\n  }\\n\\n  //  获取卡片id 数组\\n  static getList() {\\n    FormIdStore.init()\\n    const str = FormIdStore.dataPreferences?.getSync(FormIdStore.key, \'[]\')\\n    const list = JSON.parse(str as string) as string[]\\n    console.log(\\"list卡片\\", list)\\n    return list\\n  }\\n\\n  // 新增卡片数组\\n  static async set(item: string) {\\n    FormIdStore.init()\\n    const list = FormIdStore.getList()\\n    if (!list.includes(item)) {\\n      list.push(item)\\n      FormIdStore.dataPreferences?.putSync(FormIdStore.key, JSON.stringify(list))\\n      await FormIdStore.dataPreferences?.flush()\\n    }\\n\\n  }\\n\\n  // 删除元素\\n  static async remove(item: string) {\\n    FormIdStore.init()\\n    const list = FormIdStore.getList()\\n    const index = list.indexOf(item)\\n    if (index !== -1) {\\n      list.splice(index, 1)\\n      FormIdStore.dataPreferences?.putSync(FormIdStore.key, JSON.stringify(list))\\n      await FormIdStore.dataPreferences?.flush()\\n    }\\n  }\\n}\\n\\n\\n```\\n\\n\\n\\n## 2. 初始化卡片id工具类\\n\\n1. onCreate中初始化\\n\\n   > entry/src/main/ets/entryability/EntryAbility.ets\\n\\n   ```typescript\\n     onCreate(want: Want, launchParam: AbilityConstant.LaunchParam): void {\\n       FormIdStore.init(this.context)\\n   ```\\n\\n   \\n\\n2. onAddForm中初始化\\n\\n   > ```typescript\\n   > onAddForm(want: Want) {\\n   >   FormIdStore.init(this.context)\\n   > ```\\n\\n\\n\\n## 3. 卡片主动上传卡片id\\n\\n利用watch监听器来触发上传\\n\\n> entry/src/main/ets/widget/pages/WidgetCard.ets\\n\\n```typescript\\nconst localStorage = new LocalStorage()\\n\\n@Entry(localStorage)\\n@Component\\nstruct WidgetCard {\\n  @LocalStorageProp(\\"formId\\")\\n  @Watch(\\"postData\\")\\n  formId: string = \\"\\"\\n\\n  // 上传卡片id\\n  postData() {\\n    postCardAction(this, {\\n      action: \'call\',\\n      abilityName: \'EntryAbility\',\\n      params: {\\n        method: \'createCard\',\\n        formId: this.formId\\n      }\\n    });\\n  }\\n\\n  build() {\\n    Row() {\\n      Text(this.formId)\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n    .padding(10)\\n\\n  }\\n}\\n```\\n\\n\\n\\n## 4. 应用Aibility接收卡片id\\n\\n> entry/src/main/ets/entryability/EntryAbility.ets\\n\\n```typescript\\n// callee中要求返回的数据类型\\nclass MyPara implements rpc.Parcelable {\\n  marshalling(dataOut: rpc.MessageSequence): boolean {\\n    return true\\n  }\\n\\n  unmarshalling(dataIn: rpc.MessageSequence): boolean {\\n    return true\\n  }\\n}\\n\\nonCreate(want: Want, launchParam: AbilityConstant.LaunchParam): void {\\n    FormIdStore.init(this.context)\\n    // 监听事件\\n    this.callee.on(\\"createCard\\", (data: rpc.MessageSequence) => {\\n      // 接收id\\n      const formId = (JSON.parse(data.readString() as string) as Record<string, string>).formId\\n\\n      return new MyPara()\\n    })\\n  }\\n```\\n\\n\\n\\n---\\n\\n## 5. 接收卡片id并且持久化\\n\\n1. 开启后台运行权限 **\\"ohos.permission.KEEP_BACKGROUND_RUNNING\\"**\\n\\n   > entry/src/main/module.json5\\n\\n   ```json\\n       \\"requestPermissions\\": [\\n         {\\n           \\"name\\": \\"ohos.permission.INTERNET\\"\\n         },\\n         {\\n           \\"name\\": \\"ohos.permission.KEEP_BACKGROUND_RUNNING\\"\\n         }\\n       ],\\n   ```\\n\\n\\n2. 持久化\\n\\n   ```typescript\\n    onCreate(want: Want, launchParam: AbilityConstant.LaunchParam): void {\\n       FormIdStore.init(this.context)\\n       // 监听事件\\n       this.callee.on(\\"createCard\\", (data: rpc.MessageSequence) => {\\n         // 接收id\\n         const formId = (JSON.parse(data.readString() as string) as Record<string, string>).formId\\n         // 2 持久化\\n         FormIdStore.set(formId)\\n           \\n         return new MyPara()\\n       })\\n     }\\n   \\n   ```\\n\\n## 6. 移除卡片时，删除卡片id\\n\\n> entry/src/main/ets/entryformability/EntryFormAbility.ets\\n\\n```\\n  onRemoveForm(formId: string) {\\n    FormIdStore.remove(formId)\\n  }\\n```\\n\\n\\n\\n# 封装下载图片工具类\\n\\n将下载图片和拼接卡片需要格式的代码封装到文件中  该工具类可以同时下载多张图片，使用了Promise.all 来统一接收结果\\n\\n> entry/src/main/ets/utils/CardDonwLoad.ets\\n\\n## 1. 封装的工具说明\\n\\n```typescript\\ninterface IDownFile {\\n  fileName: string\\n  imageFd: number\\n}\\n\\n// 卡片显示 需要的数据结构\\nexport class FormDataClass {\\n  // 卡片需要显示图片场景, 必填字段(formImages 不可缺省或改名), fileName 对应 fd\\n  formImages: Record<string, number>\\n\\n  constructor(formImages: Record<string, number>) {\\n    this.formImages = formImages\\n  }\\n}\\n\\n\\nexport class CardDownLoad {\\n  context: Context | null\\n  then: Function | null = null\\n  imgFds: number[] = []\\n\\n  constructor(context: Context) {\\n    this.context = context\\n  }\\n\\n  // 下载单张图片\\n  async downLoadImage(netFile: string) {\\n  }\\n\\n  // 下载一组图片\\n  async downLoadImages(netFiles: string[]) {\\n  }\\n\\n  // 私有下载网络图片的方法\\n  private async _down(netFile: string) {\\n  }\\n\\n  // 手动关闭文件\\n  async closeFile() {\\n    this.imgFds.forEach(fd => fileIo.closeSync(fd))\\n    this.imgFds = []\\n  }\\n}\\n\\n\\n\\n```\\n\\n## 2. 封装的实现\\n\\n```typescript\\nimport { http } from \'@kit.NetworkKit\';\\nimport { fileIo } from \'@kit.CoreFileKit\';\\n\\n\\ninterface IDownFile {\\n  fileName: string\\n  imageFd: number\\n}\\n\\n// 卡片显示 需要的数据结构\\nexport class FormDataClass {\\n  // 卡片需要显示图片场景, 必填字段(formImages 不可缺省或改名), fileName 对应 fd\\n  formImages: Record<string, number>\\n\\n  constructor(formImages: Record<string, number>) {\\n    this.formImages = formImages\\n  }\\n}\\n\\n\\nexport class CardDownLoad {\\n  context: Context | null\\n  then: Function | null = null\\n  imgFds: number[] = []\\n\\n  constructor(context: Context) {\\n    this.context = context\\n  }\\n\\n  // 下载单张图片\\n  async downLoadImage(netFile: string) {\\n    const obj = await this._down(netFile)\\n    let imgMap: Record<string, number> = {};\\n    imgMap[obj.fileName] = obj.imageFd\\n    if (!this.imgFds.includes(obj.imageFd)) {\\n      this.imgFds.includes(obj.imageFd)\\n    }\\n    return new FormDataClass(imgMap)\\n  }\\n\\n  // 下载一组图片\\n  async downLoadImages(netFiles: string[]) {\\n    let imgMap: Record<string, number> = {};\\n\\n    const promiseAll = netFiles.map(url => {\\n      const ret = this._down(url)\\n      return ret\\n    })\\n    const resList = await Promise.all(promiseAll)\\n    resList.forEach(v => {\\n      imgMap[v.fileName] = v.imageFd\\n      if (!this.imgFds.includes(v.imageFd)) {\\n        this.imgFds.includes(v.imageFd)\\n      }\\n    })\\n\\n\\n    return new FormDataClass(imgMap)\\n    // return resList.map(v => `memory://${v.fileName}`)\\n  }\\n\\n  // 私有下载网络图片的方法\\n  private async _down(netFile: string) {\\n\\n    let tempDir = this.context!.getApplicationContext().tempDir;\\n    let fileName = \'file\' + Date.now();\\n    let tmpFile = tempDir + \'/\' + fileName;\\n\\n    let httpRequest = http.createHttp()\\n    let data = await httpRequest.request(netFile);\\n    if (data?.responseCode == http.ResponseCode.OK) {\\n\\n      let imgFile = fileIo.openSync(tmpFile, fileIo.OpenMode.READ_WRITE | fileIo.OpenMode.CREATE);\\n\\n      await fileIo.write(imgFile.fd, data.result as ArrayBuffer);\\n\\n      const obj: IDownFile = {\\n        fileName,\\n        imageFd: imgFile.fd\\n      }\\n      // setTimeout(() => {\\n      // }, 0)\\n      // fileIo.close(imgFile);\\n      httpRequest.destroy();\\n      return obj\\n    } else {\\n      httpRequest.destroy();\\n      return Promise.reject(null)\\n    }\\n\\n  }\\n\\n  // 手动关闭文件\\n  async closeFile() {\\n    this.imgFds.forEach(fd => fileIo.closeSync(fd))\\n    this.imgFds = []\\n  }\\n}\\n\\n```\\n\\n\\n\\n# 卡片发起通知，获取网络图片\\n\\n![PixPin_2024-10-31_20-52-33](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/PixPin_2024-10-31_20-52-33.gif)\\n\\n\\n\\n![image-20241031224019379](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/image-20241031224019379.png)\\n\\n1. 准备好卡片代码，用来接收返回的网络图片数据\\n2. 应用Ability接收卡片通知，下载网络图片，并且返回给卡片\\n\\n## 1. 准备好卡片代码，用来接收返回的网络图片数据\\n\\n```typescript\\nconst localStorage = new LocalStorage()\\n\\n@Entry(localStorage)\\n@Component\\nstruct WidgetCard {\\n  // 用来显示图片的数组\\n  @LocalStorageProp(\\"imgNames\\")\\n  imgNames: string[] = []\\n  // 卡片id\\n  @LocalStorageProp(\\"formId\\")\\n  @Watch(\\"postData\\")\\n  formId: string = \\"\\"\\n  // 当前显示的大图 -  和 应用-首页保持同步\\n  @LocalStorageProp(\\"activeIndex\\")\\n  activeIndex: number = 0\\n\\n  postData() {\\n    postCardAction(this, {\\n      action: \'call\',\\n      abilityName: \'EntryAbility\',\\n      params: {\\n        method: \'createCard\',\\n        formId: this.formId\\n      }\\n    });\\n  }\\n\\n  build() {\\n    Row() {\\n      ForEach(this.imgNames, (url: string, index: number) => {\\n        Image(url)\\n          .border({ width: 1 })\\n          .layoutWeight(this.activeIndex === index ? 2 : 1)\\n          .height(this.activeIndex === index ? \\"90%\\" : \\"60%\\")\\n          .borderRadius(this.activeIndex === index ? 12 : 5)\\n          .animation({ duration: 300 })\\n      })\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n    .padding(10)\\n    .backgroundImage(this.imgNames[this.activeIndex])\\n    .backgroundBlurStyle(BlurStyle.Thin)\\n    .backgroundImageSize(ImageSize.Cover)\\n    .animation({ duration: 300 })\\n  }\\n}\\n```\\n\\n## 2. 应用Ability接收卡片通知，下载网络图片，并且返回给卡片\\n\\n> entry/src/main/ets/entryability/EntryAbility.ets \\n\\n```typescript\\n// callee中要求返回的数据类型\\n\\n class MyPara implements rpc.Parcelable {\\n  marshalling(dataOut: rpc.MessageSequence): boolean {\\n    return true\\n  }\\n\\n  unmarshalling(dataIn: rpc.MessageSequence): boolean {\\n    return true\\n  }\\n}\\n\\n\\n\\nexport default class EntryAbility extends UIAbility {\\n  onCreate(want: Want, launchParam: AbilityConstant.LaunchParam): void {\\n    // 监听事件\\n    this.callee.on(\\"createCard\\", (data: rpc.MessageSequence) => {\\n      // 接收id\\n      const formId = (JSON.parse(data.readString() as string) as Record<string, string>).formId\\n      // 持久化\\n      FormIdStore.set(formId)\\n\\n      class FormData {\\n        imgName?: string[] = []\\n        activeIndex?: number = AppStorage.get(\\"activeIndex\\")!\\n      }\\n\\n      const formInfo = formBindingData.createFormBindingData(new FormData)\\n      // 先响应空数据 等待网络图片下载完毕后，再响应网络图片数据\\n      formProvider.updateForm(formId, formInfo)\\n      const cardDownLoad = new CardDownLoad(this.context)\\n      cardDownLoad.downLoadImages(AppStorage.get(\\"swiperList\\") as string[])\\n        .then(ret => {\\n          const urls = Object.keys(ret.formImages).map(v => `memory://${v}`)\\n          // 返回卡片数组\\n          class CimgNames {\\n            imgNames: string[] = urls\\n            formImages: Record<string, number> = ret.formImages\\n          }\\n\\n          const formInfo = formBindingData.createFormBindingData(new CimgNames)\\n          formProvider.updateForm(formId, formInfo)\\n          //   关闭文件\\n          cardDownLoad.closeFile()\\n        })\\n\\n\\n      // 临时处理、防止报错\\n      return new MyPara()\\n    })\\n  }\\n\\n}\\n\\n\\n```\\n\\n## 3. 效果\\n\\n![PixPin_2024-10-31_20-52-33](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/PixPin_2024-10-31_20-52-33.gif)\\n\\n\\n\\n# 卡片同步轮播\\n\\n![image-20241031224212664](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/image-20241031224212664.png)\\n\\n该功能主要是首页在图片轮播时，通知所有的卡片同时更新\\n\\n> entry/src/main/ets/pages/Index.ets\\n\\n## 1. 监听轮播图onChange事件，设置当前显示的下标\\n\\n```typescript\\n      Swiper() {\\n        ForEach(this.swiperList, (img: string) => {\\n          Image(img)\\n            .width(\\"80%\\")\\n        })\\n      }\\n      .loop(true)\\n      .autoPlay(true)\\n      .interval(3000)\\n      .onChange(index => this.activeIndex = index)\\n```\\n\\n## 2. 监听下标的改变，通知持久化存储中所有的卡片进行更新\\n\\n```typescript\\n  @StorageLink(\\"activeIndex\\")\\n  @Watch(\\"changeIndex\\")\\n  activeIndex: number = 0\\n\\n  // 通知所有卡片一并更新\\n  changeIndex() {\\n    const list = FormIdStore.getList()\\n    const index = this.activeIndex\\n    list.forEach(id => {\\n      class FdCls {\\n        activeIndex: number = index\\n      }\\n\\n      const formInfo = formBindingData.createFormBindingData(new FdCls())\\n      formProvider.updateForm(id, formInfo)\\n    })\\n  }\\n```\\n\\n## 3. 效果\\n\\n![PixPin_2024-10-31_22-18-40](HarmonyOS%20Next%20%E5%AE%9E%E6%88%98%E5%8D%A1%E7%89%87%E5%BC%80%E5%8F%91%2003.assets/PixPin_2024-10-31_22-18-40.gif)\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n# 总结\\n\\nFormExtensionAbility进程不能常驻后台，即在卡片生命周期回调函数中无法处理长时间的任务，在生命周期调度完成后会继续存在10秒，如10秒内没有新的\\n\\n生命周期回调触发则进程自动退出。针对可能需要10秒以上才能完成的业务逻辑，建议[拉起主应用](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-ui-widget-event-uiability-V5)进行处理，处理完成后使用[updateForm](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-app-form-formprovider-V5#updateform)通知卡片进行刷\\n\\n新。\\n\\n## 1. 项目开发流程\\n\\n\\n\\n1. **新建项目与服务卡片**：创建新的项目和服务卡片，为后续开发搭建基础框架。\\n2. **设置沉浸式体验**：在`EntryAbility.ets`中进行相关设置，优化用户视觉体验。\\n\\n\\n\\n## 2. 首页轮播图数据显示\\n\\n\\n\\n1. **申请网络权限**：在`module.json5`中申请，为数据获取做准备。\\n2. **新建工具文件**：在`/utils/index.ets`中创建`swiperInit`函数，用于初始化轮播图数据，包括设置轮播图列表和初始索引。\\n3. **初始化操作**：在`EntryAbility.ets`中进行初始化。\\n4. **页面使用**：在`Index.ets`中构建轮播图组件，通过`Swiper`、`ForEach`等实现轮播效果，轮播图可自动播放、循环，并能响应索引变化。\\n\\n\\n\\n## 3. 卡片 id 的处理\\n\\n\\n\\n1. **获取与返回卡片 id**：在`EntryFormAbility.ets`的`onAddForm`函数中获取卡片 id，并返回给卡片组件。原因是后期卡片向应用通信时，应用需根据卡片 id 响应，同时注意`formExtensionAbility`进程的后台限制。\\n2. **接受与显示卡片 id**：在`WidgetCard.ets`中接受并显示卡片 id。\\n3. 卡片 id 的持久化存储\\n   - **封装工具类**：在`/utils/index.ets`中封装`FormIdStore`类，实现初始化、获取卡片 id 列表、新增和删除卡片 id 等功能。\\n   - **初始化工具类**：在`EntryAbility.ets`的`onCreate`和`onAddForm`中初始化。\\n   - **卡片主动上传**：在`WidgetCard.ets`中利用`watch`监听器触发上传卡片 id。\\n   - **应用接收与持久化**：在`EntryAbility.ets`中接收卡片 id 并持久化，同时需开启后台运行权限。\\n   - **移除卡片时处理**：在`EntryFormAbility.ets`的`onRemoveForm`中删除卡片 id。\\n\\n\\n\\n## 4. 图片相关操作\\n\\n\\n\\n1. **封装下载图片工具类**：在`CardDonwLoad.ets`中封装，包括下载单张或一组图片的功能，以及手动关闭文件功能，涉及网络请求和文件操作。\\n2. 卡片发起通知获取网络图片\\n   - **卡片准备接收数据**：在`WidgetCard.ets`中准备接收网络图片数据的代码，包括显示图片数组、卡片 id 等相关变量和操作。\\n   - **应用处理与返回数据**：在`EntryAbility.ets`中接收卡片通知，下载网络图片并返回给卡片，先响应空数据，下载完成后再更新卡片数据。\\n\\n\\n\\n## 5. 卡片同步轮播功能\\n\\n\\n\\n1. **监听轮播图 onChange 事件**：在`Index.ets`中通过`Swiper`组件的`onChange`事件设置当前显示下标。\\n2. **通知卡片更新**：在`Index.ets`中监听下标改变，通知持久化存储中的所有卡片更新，实现首页与卡片轮播同步。"}'),u={name:"鸿蒙开发技巧/HarmonyOS Next 实战卡片开发/HarmonyOS Next 实战卡片开发 03/HarmonyOS Next 实战卡片开发 03.md"};function C(B,s,A,D,f,x){return p(),t("div",null,[...s[0]||(s[0]=[e("",108)])])}const q=l(u,[["render",C]]);export{v as __pageData,q as default};
